import math
import itertools
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from solution import triangle_area


def is_valid(a, b, c):
    return (a + b > c) and (a + c > b) and (b + c > a)


def heron_rounded(a, b, c):
    s = (a + b + c) / 2.0
    return round(math.sqrt(s * (s - a) * (s - b) * (s - c)), 2)


# ---- explicit examples from spec ----

def test_example_3_4_5():
    assert triangle_area(3, 4, 5) == 6.00


def test_example_invalid_1_2_10():
    assert triangle_area(1, 2, 10) == -1


def test_example_permutations_of_3_4_5():
    for p in itertools.permutations([3, 4, 5]):
        assert triangle_area(*p) == 6.00


def test_example_permutations_of_invalid():
    for p in itertools.permutations([1, 2, 10]):
        assert triangle_area(*p) == -1


# ---- explicit boundary / degenerate cases ----

def test_degenerate_sum_equals_third_returns_minus_one():
    assert triangle_area(2, 3, 5) == -1
    assert triangle_area(5, 2, 3) == -1
    assert triangle_area(2, 5, 3) == -1
    assert triangle_area(1, 1, 2) == -1
    assert triangle_area(4, 4, 8) == -1


def test_strictly_invalid_returns_minus_one():
    assert triangle_area(1, 2, 10) == -1
    assert triangle_area(1, 1, 5) == -1
    assert triangle_area(2, 3, 10) == -1


def test_equilateral_side_1_rounding():
    # sqrt(3)/4 = 0.4330... -> 0.43
    assert triangle_area(1, 1, 1) == 0.43


def test_equilateral_side_2():
    # sqrt(3) = 1.7320... -> 1.73
    assert triangle_area(2, 2, 2) == 1.73


def test_isosceles_right_unit_legs():
    # legs 1,1 hyp sqrt(2): area exactly 0.5
    assert triangle_area(1, 1, math.sqrt(2)) == 0.5


def test_right_triangle_5_12_13():
    # s=15, area = 30.0
    assert triangle_area(5, 12, 13) == 30.0


def test_right_triangle_6_8_10():
    assert triangle_area(6, 8, 10) == 24.0


# ---- property tests ----

positive_floats = st.floats(min_value=0.5, max_value=10.0,
                            allow_nan=False, allow_infinity=False,
                            width=32)
small_positive = st.floats(min_value=0.1, max_value=5.0,
                           allow_nan=False, allow_infinity=False,
                           width=32)


@given(positive_floats, positive_floats, positive_floats)
def test_property_validity_branch(a, b, c):
    assume(a > 0 and b > 0 and c > 0)
    result = triangle_area(a, b, c)
    if not is_valid(a, b, c):
        assert result == -1
    else:
        assert result != -1
        assert result > 0


@given(positive_floats, positive_floats, positive_floats)
def test_property_matches_heron_reference(a, b, c):
    assume(a > 0 and b > 0 and c > 0)
    result = triangle_area(a, b, c)
    if not is_valid(a, b, c):
        assert result == -1
    else:
        expected = heron_rounded(a, b, c)
        assert result == expected


@given(positive_floats, positive_floats, positive_floats)
def test_property_permutation_invariance(a, b, c):
    assume(a > 0 and b > 0 and c > 0)
    r0 = triangle_area(a, b, c)
    assert triangle_area(a, c, b) == r0
    assert triangle_area(b, a, c) == r0
    assert triangle_area(b, c, a) == r0
    assert triangle_area(c, a, b) == r0
    assert triangle_area(c, b, a) == r0


@given(positive_floats, positive_floats, positive_floats)
def test_property_valid_result_is_rounded_to_2_decimals(a, b, c):
    assume(is_valid(a, b, c))
    result = triangle_area(a, b, c)
    assert isinstance(result, float)
    assert result == round(result, 2)


@given(positive_floats, positive_floats, positive_floats)
def test_property_invalid_returns_exactly_minus_one(a, b, c):
    assume(not is_valid(a, b, c))
    assert triangle_area(a, b, c) == -1
    assert triangle_area(a, b, c) is not None


@given(small_positive, small_positive, st.floats(min_value=0.0, max_value=5.0,
       allow_nan=False, allow_infinity=False, width=32))
def test_property_constructed_invalid_large_side(a, b, extra):
    assume(a > 0 and b > 0 and extra >= 0)
    c = a + b + extra
    # c >= a+b so invalid (touching or exceeding)
    assert not is_valid(a, b, c)
    assert triangle_area(a, b, c) == -1
    # permutations also invalid
    assert triangle_area(c, a, b) == -1
    assert triangle_area(a, c, b) == -1


@given(st.floats(min_value=0.5, max_value=20.0, allow_nan=False, allow_infinity=False, width=32))
def test_property_equilateral_matches_closed_form(side):
    assume(side > 0)
    expected = round(math.sqrt(3) / 4.0 * side * side, 2)
    assert triangle_area(side, side, side) == expected


@given(st.integers(min_value=1, max_value=50))
def test_property_scaled_3_4_5_right_triangle(k):
    # area of (3k,4k,5k) is exactly 6k^2, no rounding ambiguity
    assert triangle_area(3 * k, 4 * k, 5 * k) == float(6 * k * k)
    assert triangle_area(3 * k, 4 * k, 5 * k) == 6.0 * k * k


@given(st.integers(min_value=1, max_value=20), st.integers(min_value=1, max_value=20))
def test_property_heron_integer_sides(x, y):
    a = float(x + 2)
    b = float(y + 2)
    # choose c valid: strictly between |a-b|+1 and a+b-1 when possible
    lo = abs(a - b) + 0.5
    hi = a + b - 0.5
    assume(lo < hi)
    c = (lo + hi) / 2.0
    assume(is_valid(a, b, c))
    assert triangle_area(a, b, c) == heron_rounded(a, b, c)
    assert triangle_area(a, b, c) > 0
